using System.ComponentModel.DataAnnotations;

namespace EmployeeManagement.Api.Entities;

// The Employee entity = one row in the Employees table.
// This is the DATABASE shape. Users never send this directly; they send a DTO.
public class Employee
{
    // "Id" by convention becomes the primary key, auto-generated by SQL Server (1, 2, 3...).
    public int Id { get; set; }

    [Required]
    [MaxLength(50)]
    public string FirstName { get; set; } = string.Empty;

    // string? = nullable: the middle name is optional, so the column allows NULL.
    [MaxLength(50)]
    public string? MiddleName { get; set; }

    [Required]
    [MaxLength(50)]
    public string LastName { get; set; } = string.Empty;

    // DateOnly = a date with no time part. Stored as a SQL "date" column.
    public DateOnly DateOfBirth { get; set; }

    [Required]
    [MaxLength(150)]
    public string Email { get; set; } = string.Empty;

    [Required]
    [MaxLength(100)]
    public string Department { get; set; } = string.Empty;

    [Required]
    [MaxLength(100)]
    public string JobTitle { get; set; } = string.Empty;

    // New employees start as Active.
    public EmployeeStatus Status { get; set; } = EmployeeStatus.Active;
}
